<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\{BelongsTo,HasMany}; class InventoryCount extends Model {protected $fillable=['count_number','warehouse_id','status','count_date','notes','created_by']; protected $casts=['count_date'=>'date']; public function warehouse():BelongsTo{return $this->belongsTo(Warehouse::class);} public function creator():BelongsTo{return $this->belongsTo(User::class,'created_by');} public function lines():HasMany{return $this->hasMany(InventoryCountLine::class);} }